from pathlib import Path
import hashlib, json, re, subprocess

HOME=Path.home()
TARGET="DEV-PRED-A2Z-DIRECT-SOL-REGRESSION-N1E36-20261007"
EXPECTED_SOURCE="b0fc664ec065c03125c54c6dae2c71126beebe67"
CAMPAIGN_ID="FULL-A2Z-LIVE-20261004-V4"
ASTRA="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
PROPOSAL="A2Z-V4-SOL-PROPOSAL-DIRECT-20261007-R4P2"
OLD_SOL="A2Z-V4-SOL-BUILD-20261007-R4"
CANDIDATE="AUTO-DISCOVERY-54d13314c7879b58e46d"

def load(p):
    return json.loads(p.read_text(encoding="utf-8"))

def fail(msg, detail=""):
    if detail:
        print("DETAIL="+detail[-12000:].replace("\x00",""))
    raise RuntimeError(msg)

# 1. Prove the already-dispatched N1E36 from its durable DEV receipt. Never rerun unittest.
statep=HOME/".local/state/prediction-project-executor"/(TARGET+".json")
receiptp=HOME/".local/share/prediction-chat-bridge/dev-task-receipts"/(TARGET+".log")
if not statep.is_file():
    fail("N1E36_STATE_MISSING")
state=load(statep)
if state.get("task_id")!=TARGET:
    fail("N1E36_STATE_TASK_MISMATCH")
if state.get("status")!="PASS":
    fail("N1E36_EXECUTOR_NOT_PASS:"+str(state.get("status")))
if state.get("source_commit")!=EXPECTED_SOURCE:
    fail("N1E36_SOURCE_COMMIT_MISMATCH:"+str(state.get("source_commit")))
wt=Path(state.get("worktree") or HOME/".local/share/prediction-project-executor/worktrees"/TARGET)
if not (wt/"tests/model_execution/test_direct_sol_chat.py").is_file():
    fail("N1E36_WORKTREE_TEST_MISSING")
if not receiptp.is_file():
    fail("N1E36_DEV_RECEIPT_MISSING")
receipt=receiptp.read_text(encoding="utf-8",errors="replace")
if f"TASK_ID={TARGET}" not in receipt or "STATUS=FINISHED" not in receipt:
    fail("N1E36_DEV_RECEIPT_ID_OR_STATUS_MISMATCH",receipt)
if not re.search(r"(?m)^EXIT_CODE=0\s*$",receipt):
    fail("N1E36_DEV_EXIT_NONZERO_OR_MISSING",receipt)
if "PROJECT_TASK_STATUS=PASS" not in receipt or "DEV_TASK_STATUS=PASS" not in receipt:
    fail("N1E36_NESTED_PASS_MISSING",receipt)
if "tests/model_execution/test_direct_sol_chat.py" not in receipt or "unittest" not in receipt:
    fail("N1E36_TARGET_TEST_NOT_IN_RECEIPT",receipt)
if not re.search(r"Ran\s+3\s+tests?\s+in",receipt):
    fail("N1E36_EXPECTED_TEST_COUNT_NOT_PROVEN",receipt)
if not re.search(r"(?m)^OK\s*$",receipt):
    fail("N1E36_UNITTEST_OK_MISSING",receipt)
if not re.search(r"PYTHON .*unittest.*tests/model_execution/test_direct_sol_chat\.py rc=0",receipt):
    fail("N1E36_OPERATION_RC0_NOT_PROVEN",receipt)
print("N1E36_DEV_RECEIPT_PROOF=PASS")
print("N1E36_SOURCE_COMMIT="+EXPECTED_SOURCE)
print("N1E36_TESTS=3")

# 2. Verify immutable R4P2 request and the actual PREBUILD payload/proposal binding.
campaign=HOME/".local/share/prediction-project-executor/campaigns"/CAMPAIGN_ID
reqp=campaign/"requests"/(ASTRA+".json")
if not reqp.is_file():
    fail("ASTRA_REQUEST_MISSING")
req=load(reqp)
for k,v in {"task_id":ASTRA,"campaign_id":CAMPAIGN_ID,"phase":"ASTRA_PREBUILD"}.items():
    if req.get(k)!=v:
        fail("ASTRA_REQUEST_"+k.upper()+"_MISMATCH:"+str(req.get(k)))
for k in ("live_trading","paid_actions","wallet_actions"):
    if req.get(k) is not False:
        fail("ASTRA_REQUEST_SAFETY_NOT_FALSE:"+k)
prompt=req.get("prompt")
if not isinstance(prompt,str) or "\nINPUT_JSON:\n" not in prompt:
    fail("ASTRA_REQUEST_INPUT_JSON_MISSING")
try:
    payload=json.loads(prompt.split("\nINPUT_JSON:\n",1)[1])
except Exception as exc:
    fail("ASTRA_REQUEST_INPUT_JSON_INVALID:"+type(exc).__name__)
if payload.get("candidate_id")!=CANDIDATE or payload.get("phase")!="PREBUILD":
    fail("ASTRA_REVIEW_PAYLOAD_CONTEXT_MISMATCH")
if payload.get("scientific_status")!="NO_PROVEN_EDGE":
    fail("ASTRA_REVIEW_PAYLOAD_SCIENCE_STATUS_MISMATCH")
if payload.get("safety")!={"live_trading":False,"paid_actions":False,"wallet_actions":False}:
    fail("ASTRA_REVIEW_PAYLOAD_SAFETY_MISMATCH")
binding=payload.get("binding_sha256")
if not isinstance(binding,str) or not re.fullmatch(r"[0-9a-f]{64}",binding):
    fail("ASTRA_PREBUILD_BINDING_SHA_INVALID")
canonical_result=Path.cwd()/"control/model_execution/direct_results"/(PROPOSAL+".json")
if not canonical_result.is_file():
    fail("CANONICAL_R4P2_RESULT_MISSING")
proposal_result=load(canonical_result)
if proposal_result.get("task_id")!=PROPOSAL or proposal_result.get("model")!="gpt-5.6-sol" or proposal_result.get("execution_layer")!="DIRECT_SOL_CHAT":
    fail("CANONICAL_R4P2_PROVENANCE_MISMATCH")
try:
    canonical_proposal=json.loads(proposal_result["final"])
except Exception as exc:
    fail("CANONICAL_R4P2_FINAL_INVALID:"+type(exc).__name__)
if payload.get("proposal")!=canonical_proposal:
    fail("ASTRA_PREBUILD_NOT_BOUND_TO_CURRENT_R4P2_PROPOSAL")
if canonical_proposal.get("candidate_id")!=CANDIDATE or canonical_proposal.get("proposal_version")!=4:
    fail("CANONICAL_R4P2_PROPOSAL_IDENTITY_MISMATCH")
print("ASTRA_PREBUILD_REQUEST_BINDING=PASS")
print("ASTRA_PREBUILD_BINDING_SHA256="+binding)

# 3. No completed PREBUILD result yet; do not create a duplicate.
resp=campaign/"model_results"/(ASTRA+".json")
if resp.is_file():
    existing=load(resp)
    print("ASTRA_EXISTING_RESULT="+json.dumps({k:existing.get(k) for k in ("task_id","phase","model","model_policy","checkpoint")},sort_keys=True))
    fail("ASTRA_PREBUILD_RESULT_ALREADY_EXISTS_STOP_AND_IMPORT")

# 4. Executable queue must contain only this intended Astra task.
models=campaign/"models"
qp=models/"TASK_QUEUE.jsonl"
if not qp.is_file():
    fail("ASTRA_TASK_QUEUE_MISSING")
rows=[]
for line in qp.read_text(encoding="utf-8",errors="replace").splitlines():
    if line.strip():
        rows.append(json.loads(line))
target=[x for x in rows if x.get("task_id")==ASTRA]
if len(target)!=1:
    fail("ASTRA_QUEUE_TARGET_COUNT:"+str(len(target)))
t=target[0]
if t.get("model_policy")!="ASTRA_EXACT":
    fail("ASTRA_QUEUE_POLICY_MISMATCH:"+str(t.get("model_policy")))
if t.get("phase") not in (None,"ASTRA_PREBUILD"):
    fail("ASTRA_QUEUE_PHASE_MISMATCH:"+str(t.get("phase")))
runnable_status={"QUEUED","WAITING_RETRY","PAUSED_USAGE_LIMIT","RUNNING"}
runnable=[x for x in rows if str(x.get("status")) in runnable_status]
if [x.get("task_id") for x in runnable] != [ASTRA]:
    fail("EXECUTABLE_QUEUE_NOT_EXCLUSIVE:"+json.dumps([{"task_id":x.get("task_id"),"status":x.get("status"),"model_policy":x.get("model_policy")} for x in runnable],sort_keys=True))
if any(x.get("task_id")==OLD_SOL and str(x.get("status")) in runnable_status for x in rows):
    fail("OLD_SOL_STILL_RUNNABLE")
print("ASTRA_QUEUE_EXCLUSIVE=PASS")
print("ASTRA_QUEUE_POLICY=ASTRA_EXACT")
print("ASTRA_QUEUE_STATUS="+str(t.get("status")))

# 5. No old resume target may be active.
for name in ("STATE.json","CONTINUATION.json"):
    p=models/name
    if not p.is_file():
        continue
    o=load(p)
    if o.get("task_id")==OLD_SOL and (o.get("state") in runnable_status or o.get("next_action")=="resume_same_task"):
        fail("OLD_SOL_RESUME_STATE_PRESENT:"+name+":"+json.dumps(o,sort_keys=True))
    if o.get("next_action")=="resume_same_task" and o.get("task_id") not in ("",ASTRA,None):
        fail("NON_ASTRA_RESUME_TARGET:"+name+":"+str(o.get("task_id")))
print("NO_OLD_CODEX_RESUME_THREAD=PASS")

# 6. Before any resume, exact instance must currently be inactive; timer must remain disabled/inactive.
unit="prediction-a2z-v4-model@"+ASTRA+".service"
timer="prediction-a2z-v4-model@"+ASTRA+".timer"
def sysctl(verb,u):
    cp=subprocess.run(["systemctl","--user",verb,u],text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=15)
    return cp.returncode,(cp.stdout or "").strip()
for verb,u,label in (("is-active",unit,"SERVICE_ACTIVE"),("is-enabled",timer,"TIMER_ENABLED"),("is-active",timer,"TIMER_ACTIVE")):
    rc,out=sysctl(verb,u)
    print(label+"_RC="+str(rc))
    print(label+"="+out)
    if label=="SERVICE_ACTIVE" and out=="active":
        fail("ASTRA_PREBUILD_SERVICE_ALREADY_ACTIVE")
    if label=="TIMER_ENABLED" and out=="enabled":
        fail("ASTRA_PREBUILD_TIMER_UNEXPECTEDLY_ENABLED")
    if label=="TIMER_ACTIVE" and out=="active":
        fail("ASTRA_PREBUILD_TIMER_UNEXPECTEDLY_ACTIVE")

print("PREBUILD_BINDING_READONLY=PASS")
print("NEXT_GATE=RESUME_EXISTING_ASTRA_PREBUILD_ONLY")
